package com.clavis.reader;
import android.app.*;import android.content.*;import android.graphics.*;import android.text.*;import android.view.*;import android.widget.*;import androidx.recyclerview.widget.RecyclerView;import java.util.*;
final class FeedPostChecks {
 static int checks;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 static RecyclerView posts(View v){if(v instanceof RecyclerView&&((RecyclerView)v).getAdapter() instanceof FeedPosts.PostAdapter)return (RecyclerView)v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){RecyclerView found=posts(((ViewGroup)v).getChildAt(n));if(found!=null)return found;}return null;}
 static void snapshot(Instrumentation test,Context c,String name)throws Exception{android.os.SystemClock.sleep(350);Bitmap b=test.getUiAutomation().takeScreenshot();java.io.File dir=new java.io.File(c.getExternalFilesDir(null),"post-review");dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,c.getResources().getConfiguration().fontScale+"-"+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 static void swipeLeft(Instrumentation test,View view){int[] location=new int[2];test.runOnMainSync(()->view.getLocationOnScreen(location));float x=location[0]+view.getWidth()*.82f,y=location[1]+view.getHeight()*.5f,end=location[0]+view.getWidth()*.22f;long down=android.os.SystemClock.uptimeMillis();android.view.MotionEvent e=android.view.MotionEvent.obtain(down,down,0,x,y,0);test.getUiAutomation().injectInputEvent(e,true);e.recycle();for(int n=1;n<=12;n++){android.os.SystemClock.sleep(15);e=android.view.MotionEvent.obtain(down,android.os.SystemClock.uptimeMillis(),2,x+(end-x)*n/12f,y,0);test.getUiAutomation().injectInputEvent(e,true);e.recycle();}e=android.view.MotionEvent.obtain(down,android.os.SystemClock.uptimeMillis(),1,end,y,0);test.getUiAutomation().injectInputEvent(e,true);e.recycle();android.os.SystemClock.sleep(350);test.waitForIdleSync();}
 static String run(Instrumentation test)throws Exception{
  checks=0;ArticleExtractionChecks.run(test);Context c=test.getTargetContext();android.content.SharedPreferences preferences=c.getSharedPreferences("appearance",0);boolean old=preferences.getBoolean("dark",true),had=preferences.contains("dark");final MainActivity[] opened={null};
  try{for(boolean dark:new boolean[]{false,true}){
   preferences.edit().putBoolean("dark",dark).commit();MainActivity a=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));opened[0]=a;test.waitForIdleSync();
   StringBuilder html=new StringBuilder();for(int n=0;n<60;n++)html.append("<p>Paragraph ").append(n).append(". This story continues across readable slides. Café, medicine, technology and the day's events stay in the same post.</p>");
   ArticleContent full=ArticleContent.extract(html.toString(),"https://example.invalid/story",true);java.io.File cached=ArticleRepository.cacheFile(c,"https://example.invalid/story");try{ArticleActivity.write(cached,full);ArticleContent loaded=ArticleRepository.load(c,"https://example.invalid/story",ArticleContent.extract("<p>Short feed preview</p>","https://example.invalid/story",true));check(loaded.characters==full.characters,"Cached full article available offline");check(StoryPages.text(loaded).equals(StoryPages.text(full)),"Cached article preserves story text");}finally{cached.delete();}
   FeedStore.Feed feed=new FeedStore.Feed();feed.url="https://example.invalid/ui-posts";feed.kind="News";feed.title="Daily stories";String image="https://example.invalid/ui-post-image";Bitmap bitmap=Bitmap.createBitmap(800,500,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(0xffdae7ed);Paint paint=new Paint(3);paint.setColor(0xff52616b);paint.setTextSize(60);canvas.drawText("A story in slides",90,270,paint);FeedArtwork.memory.put(image,bitmap);
   for(int n=0;n<3;n++){FeedStore.Item item=new FeedStore.Item();item.id="post-"+n;item.date="Sun, 25 Oct 2026 10:00:00 +0530";item.title=n==0?"Read the whole story, one swipe at a time":"Next story "+n;item.description=html.toString();item.image=n==0?image:"";feed.items.add(item);}
   feed.items.get(0).link="https://example.invalid/story";feed.items.get(0).description="<p>Short feed preview</p>";ArticleActivity.write(cached,full);try{ArticleRepository.prefetch(c,"News",java.util.Collections.singletonList(feed));check(ArticleRepository.request(c,feed.items.get(0).link,ArticleContent.extract(feed.items.get(0).description,feed.items.get(0).link,true)).get(5,java.util.concurrent.TimeUnit.SECONDS).characters==full.characters,"Home entry prefetch warms full story");test.runOnMainSync(()->FeedScreens.items(a,feed));test.waitForIdleSync();android.os.SystemClock.sleep(600);test.waitForIdleSync();}finally{cached.delete();}
   final FeedPosts.PostHolder[] card={null};test.runOnMainSync(()->{RecyclerView rv=posts(a.mainFrame);check(rv!=null,"News uses a post feed");check(rv.getAdapter().getItemCount()==3,"Stories remain separate posts");card[0]=(FeedPosts.PostHolder)rv.findViewHolderForAdapterPosition(0);check(card[0]!=null,"First post bound");FeedPosts.PostHolder h=card[0];check(h.state.loaded,"Full story loaded before swiping");check(h.state.body.equals(StoryPages.text(full)),"Full cached text replaces preview on cover");h.paginate();check(h.pager.getLayoutDirection()==View.LAYOUT_DIRECTION_LTR,"Left swipe advances story slides");check(h.slides.getItemCount()>3,"Long story spans multiple slides");check(h.pager.getCurrentItem()==0,"Image is first slide");check(h.read.getText().toString().equals("Open website"),"Publisher website action replaces article reader button");check(h.title.getTop()>=h.pager.getBottom(),"Title below image");check(h.published.getLeft()>=h.source.getRight(),"Date and time appear right of source");check(h.published.getText().toString().contains("2026")&&h.published.getText().toString().contains(":"),"Card displays publication date and time");StringBuilder rebuilt=new StringBuilder();for(StoryPages.Page p:h.state.pages)rebuilt.append(p.text);check(rebuilt.toString().equals(h.state.body),"Every story character preserved");check(h.previous.isEnabled()==false,"First slide has no previous");for(StoryPages.Page page:h.state.pages){TextView sample=FeedPosts.paragraph(a);android.text.StaticLayout measured=android.text.StaticLayout.Builder.obtain(StoryPages.spaced(page.text,a.dp(16),a.dp(3),1.16f),0,page.text.length(),sample.getPaint(),h.pager.getWidth()-a.dp(36)).setIncludePad(false).setLineSpacing(a.dp(3),1.16f).setBreakStrategy(android.graphics.text.LineBreaker.BREAK_STRATEGY_SIMPLE).build();check(measured.getHeight()<=FeedPosts.viewportHeight(a,false)-a.dp(36),"Every page fits without clipping");}h.state.loaded=true;});
   snapshot(test,c,dark?"dark-cover":"light-cover");swipeLeft(test,card[0].title);
   test.runOnMainSync(()->{FeedPosts.PostHolder h=card[0];check(h.state.item==feed.items.get(0),"Horizontal paging keeps same story");StringBuilder preserved=new StringBuilder();for(StoryPages.Page page:h.state.pages)preserved.append(page.text);check(preserved.toString().equals(h.state.body),"Expanding story card preserves all text");check(h.pager.getCurrentItem()==1,"Swiping title area advances the whole card");check(h.status.getVisibility()==View.GONE,"No bottom Story text label");check(h.title.getVisibility()==View.GONE,"Title hidden on story slides");check(h.pager.getHeight()>FeedPosts.viewportHeight(a,true),"Story viewport taller than cover");check(h.previous.isEnabled(),"Can return to image");RecyclerView inner=(RecyclerView)h.pager.getChildAt(0);FeedPosts.Slide page=(FeedPosts.Slide)inner.findViewHolderForAdapterPosition(1);check(page!=null,"Text slide visible");TextView text=page.text;check(text.getText().toString().equals(h.state.pages.get(0).text),"Slide shows expected story text");check(text.getLayout().getLineBottom(text.getLayout().getLineCount()-1)<=text.getHeight()-text.getPaddingTop()-text.getPaddingBottom()+2,"Text fits the slide");});
   snapshot(test,c,dark?"dark-text":"light-text");swipeLeft(test,card[0].pager);test.runOnMainSync(()->check(card[0].pager.getCurrentItem()==2,"Left swipe on text advances same story"));
   test.runOnMainSync(()->{FeedPosts.PostHolder h=card[0];int last=h.slides.getItemCount()-1;h.pager.setCurrentItem(last,false);check(h.state.item==feed.items.get(0),"Final slide still same story");check(!h.next.isEnabled(),"Last slide has no next");h.owner.onBindViewHolder(h,0);check(h.pager.getCurrentItem()==last,"Rebinding preserves slide position");});
   test.runOnMainSync(()->{feed.kind="Journals";FeedScreens.items(a,feed);check(posts(a.mainFrame)!=null,"Articles uses posts too");feed.kind="Podcasts";FeedScreens.items(a,feed);check(posts(a.mainFrame)==null,"Podcast episode list unchanged");a.finish();});test.waitForIdleSync();opened[0]=null;
  }}finally{if(opened[0]!=null)test.runOnMainSync(opened[0]::finish);if(had)preferences.edit().putBoolean("dark",old).commit();else preferences.edit().remove("dark").commit();AppTheme.configureColors(c);}
  FeedTabChecks.run(test);return checks+" post carousel checks passed at font scale "+c.getResources().getConfiguration().fontScale;
 }
}













